CREATE TABLE IF NOT EXISTS `courses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `course_code` varchar(255) NOT NULL,
  `course_name_en` varchar(255) NOT NULL,
  `course_name_my` varchar(255) DEFAULT NULL,
  `credit_hours` tinyint(3) unsigned NOT NULL DEFAULT 3,
  `department_id` bigint(20) unsigned DEFAULT NULL,
  `program_id` bigint(20) unsigned DEFAULT NULL,
  `pre_requisite` text DEFAULT NULL,
  `synopsis` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `course_load` decimal(5,1) DEFAULT NULL,
  `course_type_code` varchar(255) DEFAULT NULL,
  `sc_code` varchar(255) DEFAULT NULL,
  `vbe_ept_code` varchar(255) DEFAULT NULL,
  `sdg_code` varchar(255) DEFAULT NULL,
  `semester` tinyint(3) unsigned DEFAULT NULL,
  `course_plan_id` bigint(20) unsigned DEFAULT NULL,
  `alternative_group` varchar(60) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `courses_code_unique` (`course_code`),
  KEY `courses_department_id_foreign` (`department_id`),
  KEY `courses_program_id_foreign` (`program_id`),
  KEY `courses_course_plan_id_index` (`course_plan_id`),
  KEY `courses_course_type_code_foreign` (`course_type_code`),
  KEY `courses_sc_code_foreign` (`sc_code`),
  KEY `courses_vbe_ept_code_foreign` (`vbe_ept_code`),
  KEY `courses_sdg_code_foreign` (`sdg_code`),
  CONSTRAINT `courses_course_type_code_foreign` FOREIGN KEY (`course_type_code`) REFERENCES `course_types` (`code`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `courses_department_id_foreign` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `courses_program_id_foreign` FOREIGN KEY (`program_id`) REFERENCES `programs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `courses_sc_code_foreign` FOREIGN KEY (`sc_code`) REFERENCES `mqf_sc` (`code`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `courses_sdg_code_foreign` FOREIGN KEY (`sdg_code`) REFERENCES `sdgs` (`code`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `courses_vbe_ept_code_foreign` FOREIGN KEY (`vbe_ept_code`) REFERENCES `vbe` (`code`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=290 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

